i32 string_to_int(const char* str)
{
	i32 result = 0;
	i32 sign = 1; //numbers are positive by default

	//skip whitespace
	while (*str == ' ' || *str == '\t' || *str == '\n')
	{
		str++;
	}

	//handle sign
	if (*str == '-')
	{
		sign = -1;
		str++;
	} else if (*str == '+'){
		str++;
	}

	//main conversion
	while (*str >= '0' && *str <= '9')
	{
		result = result * 10 + (*str - '0');
		str++;
	}

	return result * sign;
}

static int str_has_prefix(const char* str, const char *prefix)
{
    while (*prefix)
    {
        if (*prefix != *str) return 0;
        prefix++;
        str++;
    }
    return 1;
}

