typedef struct
{
	u64 base_address;
	u64 length;
	u32 type;	//type 1, usable RAM; type 2, reserved hardware
	u32 acpi_extended;
} __attribute__((packed)) MemoryMapEntry;

#define _BLOCK_SIZE 4096

//place bitmap safely at 1MB, this avoids overwriting the bootloader
static u32 *pmm_bitmap = (u32*)0x100000;
static u32 max_blocks = 0;
static u32 used_blocks = 0;

//inline bit manipulation helper methods...
static inline void bitmap_set(u32 bit)
{
	pmm_bitmap[bit / 32] |= (1 << (bit % 32));
}

static inline void bitmap_clear(u32 bit)
{
	pmm_bitmap[bit / 32] &= ~(1 << (bit % 32));
}

static inline int bitmap_test(u32 bit)
{
	return (pmm_bitmap[bit / 32] & (1 << (bit % 32))) != 0;
}

//sets a range of blocks as free (0)...
void pmm_init_region(u32 base_addr, u32 size)
{
	u32 align = base_addr / _BLOCK_SIZE;
	u32 blocks = size / _BLOCK_SIZE;

	for (; blocks > 0; blocks--)
	{
        u32 bit = align++;
        //only decrement if the page frame waas previously marked as used
        if (bitmap_test(bit))
        {
            bitmap_clear(bit);
            used_blocks--;
        }
	}
}

//sets a range of blocks as used (1)...
void pmm_deinit_region(u32 base_addr, u32 size)
{
	u32 align = base_addr / _BLOCK_SIZE;
	u32 blocks = size / _BLOCK_SIZE;

	for (; blocks > 0; blocks--)
	{
        u32 bit = align++;
        //only increment counter if the page frame was previously marked as free
		if (!bitmap_test(bit))
        {
            bitmap_set(bit);
		    used_blocks++;
	    }
    }
}

//primary PMM(Physical Memory Manager) initialization method...
void pmm_init(u32 memory_entries_count, MemoryMapEntry* mmap_entries)
{
	u64 total_memory = 0;

	//find the highest memory address to calculate how many total blocks needed
	for (u32 i = 0; i < memory_entries_count; ++i)
	{
		if (mmap_entries[i].type == 1)
		{
			u64 end_addr = mmap_entries[i].base_address + mmap_entries[i].length;
			if (end_addr > total_memory)
			{
				total_memory = end_addr;
			}
		}
	}

	max_blocks = (u32)(total_memory / _BLOCK_SIZE);
	used_blocks = max_blocks;

    u32 bitmap_dwords = (max_blocks + 31) / 32;

	//by default, mark ALL memory as reserved, set all bits to 1...
	for (u32 i = 0; i < bitmap_dwords; ++i)
	{
		pmm_bitmap[i] = 0xFFFFFFFF;
	}

	//free only the regions marked as type 1(usable) by the BIOS
	for (u32 i = 0; i < memory_entries_count; ++i)
	{
		if (mmap_entries[i].type == 1)
		{
			pmm_init_region((u32)mmap_entries[i].base_address, (u32)mmap_entries[i].length);
		}
	}

	//protect kernel space!
	pmm_deinit_region(0x0000, 0x150000);
}

//finds the first free bit (0) in the bitmap, sets it to one and return the physical address
//since you already know memory alocators return void pointer hehe...
void* pm_alloc_block()
{
	if (max_blocks - used_blocks <= 0) return NULL;

    u32 bitmap_dwords = (max_blocks + 31) / 32;
	for (u32 i = 0; i < bitmap_dwords; ++i)
	{
		if (pmm_bitmap[i] != 0xFFFFFFFF) //if this 32 chuck isn't filled(0xFFFFFFFF)
		{
			for (int j = 0; j < 32; j++)
			{
				u32 bit = i * 32 + j;
                if (bit >= max_blocks) return NULL; //do ont allocate beyomd physics
			
                if (!bitmap_test(bit))
                {
                    bitmap_set(bit);
                    used_blocks++;
                    return (void*)(bit * _BLOCK_SIZE);
                }
            }
		}
	}
	return NULL;
}

//we have to implement a free to avoid memory leakage...
void pmm_free_block(void* ptr)
{
	u32 addr = (u32)ptr;
	u32 bit = addr / _BLOCK_SIZE;

	bitmap_clear(bit);
 	used_blocks--;
}

//VMM (Virtual Memory Manager), Hardware Paging...

#define _PAGE_PRESENT 0x1 //bit 0: 1 = page is in RAM
#define _PAGE_WRITE 0x2   //bit 1: 1 = Read/write, 0 = Read-Only
#define _PAGE_USER 0x4    //bit 2: 1 = User mode (Ring 3), 0 = Kernel space (Ring 0)

static u32 *kernel_page_directory = NULL;

static inline void tlb_flush_single(u32 virt_addr)
{
    __asm__ volatile("invlpg (%0)" :: "r"(virt_addr) : "memory");
}

//maps a specific va(virtual address) to a physical frame address
void vmm_map_page(u32 *page_dir, u32 virtual_addr, u32 physical_addr, u32 flags)
{
	//a 32 bit va contains a 10-bit directory index and a 10-bit table
	u32 dir_index = virtual_addr >> 22;
	u32 table_index = (virtual_addr >> 12) & 0x3FF;

	//check if page table exists for this directory entry
	if (!(page_dir[dir_index] & _PAGE_PRESENT))
	{
		//if it doesnt exist call the PMM to allocate a clear physical frame to a page table entry...
		u32 *new_table = (u32*)pm_alloc_block();

		//zero out the new brand page table
		for (int i = 0; i < 1024; ++i)
		{
			new_table[i] = 0;
		}

		//place physical address of the page table inside the directory entry
		page_dir[dir_index] = (u32)new_table | flags | _PAGE_PRESENT;
	}

	//extract the page table physical address (clearing out lower flags)
	u32 *page_table = (u32*)(page_dir[dir_index] & ~0xFFF);

	page_table[table_index] = physical_addr | flags | _PAGE_PRESENT;

    tlb_flush_single(virtual_addr);
}

void vmm_init()
{
	//allocate a 4KB block from our PMM to serve as MPD(Master Page Directory)
	kernel_page_directory = (u32*)pm_alloc_block();

	//clear out the directory
	for (int i = 0; i < 1024; ++i)
	{
		kernel_page_directory[i] = 0;
	}

	//identity map the first 8MB of memory space
	for (u32 i = 0; i < 0x800000; i += _BLOCK_SIZE)
	{
		vmm_map_page(kernel_page_directory, i, i, _PAGE_WRITE);
	}

	//time to talk to ze hardware assembly lines arrrgh!
	// load base address of out directory layout into ze CPU CR3 register
	__asm__ volatile("mov %0, %%cr3" : : "r"(kernel_page_directory)); //in-line assembly

	//read cr0(control register, remember the register we used to enter PM(Protected Mode))
	//and write it back out
	u32 cr0;
	__asm__ volatile("mov %%cr0, %0" : "=r"(cr0));
	cr0 |= 0x80000000; //toggle the PG Flag bit
	__asm__ volatile("mov %0, %%cr0" : : "r"(cr0));
}

//Heap manipulation hehe
// KMALLOC and KFREE (our own custom memory allocator and memory cleaner (free))

typedef struct Header
{
	struct Header *next;
	u32 size;
	int is_free;
}__attribute__((packed)) Header;

#define _HEAP_START_ADDR 0x1000000 //16 MB virtual boundary
static Header *heap_start = NULL;

void kheap_init(u32 initial_pages)
{
    u32 virt = _HEAP_START_ADDR;

    for (u32 i = 0; i < initial_pages; ++i)
    {
        void* phys = pm_alloc_block();
        if (!phys)
        {
            //memory allocation failure
            return;
        }
        vmm_map_page(kernel_page_directory, virt, (u32)phys, _PAGE_WRITE | _PAGE_PRESENT);
        virt += _BLOCK_SIZE; //addvance virtual address sequentially
    }

    heap_start = (Header*)_HEAP_START_ADDR;
    heap_start->next = NULL;
    heap_start->size = (initial_pages * _BLOCK_SIZE) - sizeof(Header);
    heap_start->is_free = 1;
}

void* kmalloc(u32 size)
{
	Header* curr = heap_start;

	while(curr)
	{
		if (curr->is_free && curr->size >= size)
		{
			//can we split to presevers leftover space? sure we can!
			if (curr->size >= size + sizeof(Header) + 4)
			{
				Header *new_block = (Header*)((u32)curr + sizeof(Header) + size);
				new_block->next = curr->next;
				new_block->size = curr->size - size - sizeof(Header);
				new_block->is_free = 1;

				curr->next = new_block;
				curr->size = size;
			}

			curr->is_free = 0;
			//hand back the pointer immediately following the metadata header
			return (void*)((u32)curr + sizeof(Header));
		}
		curr = curr->next;
	}

	return NULL; //only reaches here when heap is exhausted!
}

//free, de-allocate memory in the heap...
void kfree(void *ptr)
{
	if (!ptr) return;

	Header *header = (Header*)((u32)ptr - sizeof(Header));
	header->is_free = 1;

	Header* curr = heap_start;
	while (curr)
	{
		if (curr->is_free && curr->next && curr->next->is_free)
		{
            //merge next bock into current block, for example block A and B
			curr->size += sizeof(Header) + curr->next->size;
			curr->next = curr->next->next;
		} else {
            curr = curr->next;
        }
	}
}

#define _VFS_FILE 0x01
#define _VFS_DIRECTORY 0x02
#define _VFS_DEVICE 0x03

//the global anchor of our system directory tree
static vfs_node_t *vfs_root = NULL;

//VFS core API wrappers...
u32 vfs_read(vfs_node_t *node, u32 offset, u32 size, u8 *buffer)
{
	if (node && node->read)
	{
		//execute the function adress stored inside this specific node
		return node->read(node, offset, size, buffer);
	}

	return 0;
}

//is this correctly implemented?
u32 vfs_write(vfs_node_t *node, u32 offset, u32 size, u8* buffer)
{
	if (node && node->write)
	{
		return node->write(node, offset, size, buffer);
	}
	return 0;
}

//recursively walk path components...
vfs_node_t* vfs_find_path(vfs_node_t *root, const char *path)
{
	if (!root || !path || path[0] != '/') return NULL;
	if (path[1] == '\0') return root;

	char element[128];
	u32 p_idx = 1; //skip the leading root slash
	vfs_node_t *current_node = root;

	while (path[p_idx] != '\0')
	{
		u32 e_idx = 0;
		//parse out individual folder/file names between slashes
		while (path[p_idx] != '/' && path[p_idx] != '\0')
		{
			if(e_idx < 127)
			{
				element[e_idx++] = path[p_idx];
			}
			p_idx++;
		}
		element[e_idx] = '\0';

		if (path[p_idx] == '/') p_idx++;

		if (current_node->finddir)
		{
			//ASK the current directory node to look up the parsed element string
			current_node = current_node->finddir(current_node, element);
			if (!current_node) return NULL; //Not found!
		} else {
			return NULL; //hit a file instead of a folder directory
		}
	}
	return current_node;
}

static FAT32_BPB *mounted_bpb = NULL;
static u32 fat_start_sector = 0;
static u32 data_start_sector = 0;

