static u32 current_dir_cluster = 2; //defaultt fallback to Cluster 2, FAT32 standard root

//a simple in-memory test driver
static vfs_node_t* mock_bin_dir = NULL;
static vfs_node_t* mock_test_file = NULL;

//this function matches 'vfs_finddir_type' signature perfectly!
vfs_node_t* mock_root_finddir(vfs_node_t* node, const char* name)
{
	if (strcmp(name, "bin") == 0) return mock_bin_dir;
	return NULL;
}

//this function matches the 'vfs_finddir_type' signature perfectly!
vfs_node_t* mock_bin_finddir(vfs_node_t* node, const char* name)
{
	if (strcmp(name, "hello.txt") == 0) return mock_test_file;
	return NULL;
}

//this function matches 'vfs_read_type' signature perfectly!
u32 mock_file_read(vfs_node_t* node, u32 offset, u32 size, u8* buffer)
{
	const char *text = "UROS Node System is Cooking Live!";
	u32 len = 0;
	while (text[len]) len++; //simple length check

	if (offset >= len) return 0;
	if (offset + size > len) size = len - offset;

	//copy out the raw memory string payload
	for (u32 i = 0; i  < size; ++i)
	{
		buffer[i] = (u8)text[offset + i];
	}
	return size;
}

void vfs_init(int mount_hardware)
{
	// 1. Allocate root container directory dynamically on the heap
	vfs_root = (vfs_node_t*)kmalloc(sizeof(vfs_node_t));
	vfs_root->type = _VFS_DIRECTORY;

	if (mount_hardware)
	{
		vga_puts("[ VFS ] - Mounting raw IDE storage system to '/'...\n");

		vga_puts("[ VFS ] - Querying hardware storage systems... \n");

		if (fat32_init())
		{
			vga_puts("[ OK ] - FAT32 Volume mapped successfully to '/' \n");
			vfs_root->type = 0x02;  //uses the real field
			vfs_root->inode = mounted_bpb->root_cluster;
			vfs_root->size = 0;
			vfs_root->finddir = fat32_finddir;
			vfs_root->write = fat32_write;
			
			//initialize out tracking state to the actual drive's root cluster
			current_dir_cluster = mounted_bpb->root_cluster;
		} else {
			vga_puts("[ ERROR ] - FAT32 initialization failed falling back to RAM LAyouts. \n");
			mount_hardware = 0; //flip flag to trigger RAM fallback
		}
	}
	else
	{
		vga_puts("[ VFS ] - No hardware mounted. Seeding RAM-backed file node arrays...\n");
		vfs_root->finddir = mock_root_finddir; // Hook up memory lookups!

		// 2. Allocate our virtual /bin folder
		mock_bin_dir = (vfs_node_t*)kmalloc(sizeof(vfs_node_t));
		mock_bin_dir->type = _VFS_DIRECTORY;
		mock_bin_dir->finddir = mock_bin_finddir;

		// 3. Allocate a mock text file inside the heap area
		mock_test_file = (vfs_node_t*)kmalloc(sizeof(vfs_node_t));
		mock_test_file->type = _VFS_FILE;
		mock_test_file->read = mock_file_read;
	}
}

int fat32_init(void)
{
	//allocate a 512 byte buffer on the heap to store the sector data
	u8 *sector_buffer = (u8*)kmalloc(512);
	if (!sector_buffer)
	{
		vga_puts("[ FAT32 ] - Heap allocation failed for sector buffer. \n");
		return 0;
	}

	//read sector 0 (the boot sector) from our primary slave IDE disk
	ata_read_sector(0, sector_buffer);

	//safety check, verify the boot signature (0xaa55)
	u16 boot_signature = *(u16*)(sector_buffer + 510);
	if (boot_signature != 0xAA55)
	{
		vga_puts("[ FAT32 ERROR ] - Sector 0 boot signature invalid, Found: ");
		vga_put_hex(boot_signature);
		vga_puts("\n");
		kfree(sector_buffer);
		return 0;
	}

	//detect idf sector 0 is an MBR or directly the VBR(Volume Boot Record)
	//valid FAT filesystems always begin with an assembly jump instruction (0xEB or 0xE9)
	u8 first_byte = sector_buffer[0];
	u32 target_sector = 0;

	if (first_byte != 0xEB && first_byte != 0xE9)
	{
		vga_puts("[ MBR ] - Partition Table structure detected inside Sector 0. \n");
		MBR_Sector *mbr = (MBR_Sector*)sector_buffer;
		int found_partition = 0;

		for (int i = 0; i < 4; i++)
		{
			//check fot FAT32 Type Identifiers (0x0B = CHS, 0x0C = LBS mapped)
			if (mbr->partitions[i].part_type == 0x0B || mbr->partitions[i].part_type == 0x0C)
			{
				target_sector = mbr->partitions[i].lba_start;
				vga_puts("      Found valid FAT32 partition at LBA Sector: ");
				vga_put_num(target_sector);
				vga_puts("\n");
				found_partition = 1;
				break;
			}
		}

		if (!found_partition)
		{
			vga_puts("[ MBR ERROR ] - No valid FAT32 Volumes found in the partition table. \n");
			kfree(sector_buffer);
			return 0;
		}
	} else {
		vga_puts("[ VBR ] - Flat image layout detected. Sector 0 matches a raw VBR entry directly. \n");
		target_sector = 0;
	}

	//set our absolute volume baseline sector positioning point
	partition_offset = target_sector;

	//load the genuine filesystem descriptor block (VBR) from the computed offset
	ata_read_sector(partition_offset, sector_buffer);
	mounted_bpb = (FAT32_BPB*)sector_buffer;

	boot_signature = *(u16*)(sector_buffer + 510);
	if (boot_signature != 0xAA55)
	{
		vga_puts("[ FAT32 ERROR ] - VBR block verification signature failed! \n");
		kfree(sector_buffer);
		return 0;
	}

	vga_puts("[ FAT32 ] - Mounting media filesystem volumes...\n");
	vga_puts("      OEM Label: ");
	for (int i = 0; i < 8; ++i) vga_put_c(mounted_bpb->oem_name[i]);
	vga_puts("\n");

	//calculate core cluster offset boundaries
	// the File Allocation Table(FAT) starts right after the reserved sectors
	fat_start_sector = mounted_bpb->reserved_sector_count;

	//the data region starts after the reserved sectors and all copies of the FAT tables
	data_start_sector = mounted_bpb->reserved_sector_count + (mounted_bpb->num_fats * mounted_bpb->fat_size_32);
	vga_puts("      Sectors Per Cluster: ");
	vga_put_num(mounted_bpb->sectors_per_cluster);
	vga_puts("\n      FAT Start Sector: ");
	vga_put_num(fat_start_sector);
	vga_puts("\n      Data Region Start: ");
	vga_put_num(data_start_sector);
	vga_puts("\n");

	return 1; //successfully mounted!
}

u32 fat32_read(struct vfs_node *node, u32 offset, u32 size, u8 *buffer)
{
	if (!node || mounted_bpb == NULL || size == 0) return 0;

	//safety constraint: clamp readinf bounds file size
	if (offset >= node->size) return 0;
	if (offset + size > node->size) size = node->size - offset;

	u32 bytes_per_cluster = mounted_bpb->sectors_per_cluster * 512;
	u32 start_cluster = node->inode;

	//skip clusters if the read offset is deeper than cluster 0
	u32 cluster_skip = offset / bytes_per_cluster;
	u32 current_cluster = start_cluster;

	u8 *fat_sector_buffer = (u8*)kmalloc(512);
	if (!fat_sector_buffer) return 0;

	for (u32 i = 0; i < cluster_skip; ++i)
	{
		//compute which sector of the FAT map contains entry for current cluster
		u32 fat_sector = partition_offset + fat_start_sector + ((current_cluster * 4) / 512);
		u32 fat_offset = (current_cluster * 4) % 512;

		ata_read_sector(fat_sector, fat_sector_buffer);
		current_cluster = *(u32*)&fat_sector_buffer[fat_offset] & 0x0FFFFFFF;

		if (current_cluster >= 0x0FFFFFF8)
		{
			kfree(fat_sector_buffer);
			return 0; //unexpected early EOF(End Of File)
		}
	}

	//read data into the target buffer
	u32 bytes_read = 0;
	u32 cluster_offset = offset % bytes_per_cluster;
	u8* cluster_buffer = (u8*)kmalloc(bytes_per_cluster);
	if (!cluster_buffer)
	{
		kfree(fat_sector_buffer);
		return 0;
	}

	while (bytes_read < size)
	{
		//map phyiscal storage sectors matching this data cluster
		u32 start_sector = fat32_cluster_to_sector(current_cluster);

		//read the entire cluster into a temporary struct
		for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
		{
			ata_read_sector(start_sector + s, cluster_buffer + (s * 512));
		}

		//how much data is gonna be copied from this cluster
		u32 chunk_size = bytes_per_cluster - cluster_offset;
		if (chunk_size > (size - bytes_read)) chunk_size = size - bytes_read;
		//transfer raw data to the user space buffer
		for (u32 i = 0; i < chunk_size; ++i)
		{
			buffer[bytes_read + i] = cluster_buffer[cluster_offset + i];
		}

		bytes_read += chunk_size;
		cluster_offset = 0; //only the first clutser has original file offset
		u32 fat_sector = partition_offset + fat_start_sector + ((current_cluster * 4) / 512);
		u32 fat_offset = (current_cluster * 4) % 512;

		ata_read_sector(fat_sector, fat_sector_buffer);
		current_cluster = *(u32*)&fat_sector_buffer[fat_offset] & 0x0FFFFFFF;

		if (current_cluster >= 0x0FFFFFF8) break; //break out if EOF reached
	}

	kfree(cluster_buffer);
	kfree(fat_sector_buffer);
	return bytes_read;
}

u32 fat32_write(struct vfs_node* node, u32 offset, u32 size, u8* buffer)
{
	if (!node || mounted_bpb == NULL || size == 0) return 0;

	u32 bytes_per_clutser = mounted_bpb->sectors_per_cluster * 512;
	u32 current_cluster = node->inode;
    u32 initial_cluster = node->inode;

    //1. allocate initial cluster if file is brand new
    if (node->inode == 0)
    {
        u32 first_cluster = fat32_find_free_cluster();
        if (first_cluster == 0) return 0; //ze memory has been uh expended
        
        fat32_write_fat_entry(first_cluster, 0x0FFFFFFF); //Mark EOF
        node->inode = first_cluster;
        current_cluster = first_cluster; //Fix: keeping current_cluster in sync
        initial_cluster = first_cluster;
    }

    u32 cluster_skip = offset / bytes_per_clutser; //cluster_skip from offset

	u8* fat_sector_buffer = (u8*)kmalloc(512);
	if (!fat_sector_buffer) return 0;

    u32 last_cluster = current_cluster;

	//follow cluster chain to the offset location
	for (u32 i = 0; i < cluster_skip; i++)
	{
		u32 fat_sector = partition_offset + fat_start_sector + ((current_cluster * 4) / 512);
		u32 fat_offset = (current_cluster * 4) % 512;

		ata_read_sector(fat_sector, fat_sector_buffer);
		last_cluster = current_cluster;
		current_cluster = *(u32*)&fat_sector_buffer[fat_offset] & 0x0FFFFFFF;

		//allocate a new cluster chain link if writing way part current allocated clusters
		if (current_cluster >= 0x0FFFFFF8 || current_cluster == 0)
		{
			u32 free_cluster = fat32_find_free_cluster();
			if (free_cluster == 0)
			{
				kfree(fat_sector_buffer);
				return  0; //disk full!
			}
			fat32_write_fat_entry(last_cluster, free_cluster);
			fat32_write_fat_entry(free_cluster, 0x0FFFFFFF); //mark new EOF
			current_cluster =  free_cluster;
		}
	}

	u32 bytes_written = 0;
	u32 cluster_offset = offset % bytes_per_clutser;
	u8* cluster_buffer = (u8*)kmalloc(bytes_per_clutser);
	if (!cluster_buffer)
	{
			kfree(fat_sector_buffer);
			return 0;
	}

	//2. Main byte streaming loop
	while (bytes_written < size)
	{
		u32 start_sector = fat32_cluster_to_sector(current_cluster);

		//read the cluster first to preserve data boundaries we aren't changing
		for (u32 s = 0;  s < mounted_bpb->sectors_per_cluster; s++)
		{
			ata_read_sector(start_sector + s, cluster_buffer + (s * 512));
		}

		u32 chunk_size = bytes_per_clutser - cluster_offset;
		if (chunk_size > (size - bytes_written))
		{
			chunk_size = size - bytes_written;
		}

		//pverwrite the specific window inside ze cluster buffer
		for (u32 i = 0; i < chunk_size; i++)
		{
			cluster_buffer[cluster_offset + i] = buffer[bytes_written + i];
		}

		//commit full cluster data changes down to disk
		for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
		{
			ata_write_sector(start_sector + s, cluster_buffer + (s * 512));
		}

		bytes_written += chunk_size;
		cluster_offset  = 0; //subsequent loops write from cluster start line

		if (bytes_written < size)
		{
			u32 fat_sector = partition_offset + fat_start_sector + ((current_cluster * 4) / 512);
			u32 fat_offset = (current_cluster * 4) % 512;

			ata_read_sector(fat_sector, fat_sector_buffer);
			last_cluster = current_cluster;
			current_cluster = *(u32*)&fat_sector_buffer[fat_offset] & 0x0FFFFFFF;

			//allocate next chain node if file expansion is required
			if (current_cluster >= 0x0FFFFFF8 || current_cluster == 0)
			{
				u32 free_cluster = fat32_find_free_cluster();
				if (free_cluster == 0) break; //out of memory block bounds,  write what we can
				fat32_write_fat_entry(last_cluster, free_cluster);
				fat32_write_fat_entry(free_cluster, 0x0FFFFFFF);
				current_cluster = free_cluster;
			}
		}
	}

    u32 final_size = offset + bytes_written;
    if (final_size > node->size || initial_cluster != node->inode)
    {
        node->size = final_size;
        //flushes update starting cluster and size back to directory sectors
        fat32_sync_directory_metadata(node, current_dir_cluster, node->size, node->inode);
    }

	kfree(cluster_buffer);
	kfree(fat_sector_buffer);
	return bytes_written;
}

//converts a FAT32 Cluster index into a aw logical block address sector
u32 fat32_cluster_to_sector(u32 cluster)
{
	if (cluster < 2) return 0; //clusters 0 and 1 are invalid boundary tags
	return partition_offset + data_start_sector + ((cluster - 2) * mounted_bpb->sectors_per_cluster);
}

//custom helper that compares normal input string (eg. "bin")
// returns 0 on a perfect match...
int fat32_compare_name(const char* input_name, const u8* fat_name)
{
	char formatted_input[11];
	//pre-fill outr comparison buffer with standard FAT empty spaces
	for (int i = 0; i < 11; ++i) formatted_input[i] = ' ';

	int i = 0;
	//process main file/folder name postion (up to 8 bytes)
	while (input_name[i] != '\0' && input_name[i] != '.' && i < 8)
	{
		char c = input_name[i];
		if (c >= 'a' && c <= 'z') c -= 32; //convert to upper case...
		formatted_input[i] = c;
		i++;
	}

	if (input_name[i] == '.')
	{
		i++; //skipp the '.' character
		int ext_idx = 8;
		while (input_name[i] != '\0' && ext_idx < 11)
		{
			char c = input_name[i];
			if (c >= 'a' && c <= 'z') c -= 32;
			formatted_input[ext_idx] = c;
			i++;
			ext_idx++;
		}
	}

	//compare the raw 11 bytes completely
	for (int idx = 0;  idx < 11; idx++)
	{
		if (formatted_input[idx] != fat_name[idx])
		{
			return 1; //msimatch encountered
		}
	}
	return 0; //perfect match found!
}

struct vfs_node *fat32_finddir(struct vfs_node *dir_node, const char* name)
{
	//ensure we are working on a directory flag (0x02)
	if (!(dir_node->type & 0x02) || mounted_bpb == NULL) return NULL;

    u32 current_cluster = dir_node->inode;
    u32 bytes_per_sector = 512;
    u8 *buffer = (u8*)kmalloc(bytes_per_sector);
    if (!buffer) return NULL;

    u8 *fat_buffer = (u8*)kmalloc(bytes_per_sector);
    if (!fat_buffer) { kfree(buffer); return NULL; }

    //TRaverse the full cluster chain of the directory...
    while (current_cluster < 0x0FFFFFF8 && current_cluster != 0)
    {
        u32 start_sector = fat32_cluster_to_sector(current_cluster);

        //loop through EVERY sector inside the cluster....
        for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
        {
            ata_read_sector(start_sector + s, buffer);
            FAT32_DirEntry* entries = (FAT32_DirEntry*)buffer;

            for (int i = 0; i < 16; ++i)
            {
                if (entries[i].name[0] == 0x00) //End of directory stream...
                {
                    kfree(buffer);
                    kfree(fat_buffer);
                    return NULL;
                }
                if (entries[i].name[0] == 0xE5) continue; //deleted entry
                if (entries[i].attr == 0x0F) continue; //LFN entry
                if (entries[i].attr & 0x08) continue; //Volume Label
            
                if (fat32_compare_name(name, entries[i].name) == 0)
                {
                    struct vfs_node *child = (struct vfs_node*)kmalloc(sizeof(struct vfs_node));
                    if (!child) { kfree(buffer); kfree(fat_buffer); return NULL; }

                    //construct name and attributes
                    int c;
                    for (c = 0; c < 8 && entries[i].name[c] != ' '; c++)
                    {
                        child->name[c] = entries[i].name[c];
                    }
                    if (!(entries[i].attr & 0x10) && entries[i].name[8] != ' ')
                    {
                        child->name[c++] = '.';
                        for (int e = 8; e < 11 && entries[i].name[e] != ' '; e++)
                        {
                            child->name[c++] = entries[i].name[e];
                        }
                    }
                    child->name[c] = '\0';

                    child->size = entries[i].file_size;
                    child->inode = ((u32)entries[i].first_cluster_hi << 16) | entries[i].first_cluster_lo;
                
                    if (entries[i].attr & 0x10)
                    {
                        child->type = 0x02;
                        child->finddir = fat32_finddir; //its recursive?
                        child->read = NULL;
                        child->write = NULL;
                    } else {
                        child->type = 0x01;
                        child->finddir = NULL;
                        child->read = fat32_read;
                        child->write = fat32_write;
                    }

                    child->open = NULL;
                    child->close = NULL;

                    kfree(buffer);
                    kfree(fat_buffer);
                    return child;
                }
            }
        }

        //fetch next cluster from FAT table
        u32 fat_sector = partition_offset + fat_start_sector + ((current_cluster * 4) / 512);
        u32 fat_offset = (current_cluster * 4) % 512;
        ata_read_sector(fat_sector, fat_buffer);
        current_cluster = *(u32*)&fat_buffer[fat_offset] & 0x0FFFFFFF;
    }

    kfree(buffer);
    kfree(fat_buffer);
    return NULL;
}

int fat32_create_dir(u32 parent_cluster, const char* dirname)
{
	if (mounted_bpb == NULL) return 0;

	//claim ze free cluster
	u32 new_clus = fat32_find_free_cluster();
	if (new_clus == 0)
	{
		vga_puts("[ MKDIR ERROR ] - No free clusters available. \n");
		return 0;
	}

	//mark as EOF
	fat32_write_fat_entry(new_clus, 0x0FFFFFFF);

	//clear the allocated cluster memory
	u32 bytes_per_cluster = mounted_bpb->sectors_per_cluster * 512;
	u8* cluster_buffer = (u8*)kmalloc(bytes_per_cluster);
	if (!cluster_buffer) return 0;
	memset(cluster_buffer, 0, bytes_per_cluster);

	//structure the initial directory contents
	FAT32_DirEntry *entries = (FAT32_DirEntry*)cluster_buffer;

	// set up "." entry (current directory)
	memset(entries[0].name, ' ', 11);
	entries[0].name[0] = '.';
	entries[0].attr = 0x10; //attribute for directory
	entries[0].first_cluster_hi = (new_clus >> 16) & 0xFFFF;
	entries[0].first_cluster_lo = new_clus & 0xFFFF;
	entries[0].file_size = 0;

	//setup ".." entry (previous directory)
	memset(entries[1].name, ' ', 11);
	entries[1].name[0] = '.';
	entries[1].name[1] = '.';
	entries[1].attr = 0x10;

	u32 parent_target_val = (parent_cluster == mounted_bpb->root_cluster) ? 0 : parent_cluster;
	entries[1].first_cluster_hi = (parent_target_val >> 16) & 0xFFFF;
	entries[1].first_cluster_lo = parent_target_val & 0xFFFF;
	entries[1].file_size = 0;

	//commit these formatted entries onto the new sector
	u32 start_sector = fat32_cluster_to_sector(new_clus);
	for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
	{
		ata_write_sector(start_sector + s, cluster_buffer + (s * 512));
	}
	kfree(cluster_buffer);

	return fat32_add_entry(parent_cluster, dirname, 0x10, new_clus, 0);
}

//write new value to a specific slot in the FAT on the disk
void fat32_write_fat_entry(u32 cluster, u32 value)
{
	if (mounted_bpb == NULL) return;

	//each FAT entry is 4 bytes (32 bit)
	u32 fat_sector = partition_offset + fat_start_sector + ((cluster * 4) / 512);
	u32 fat_offset = (cluster * 4) % 512;

	u8 *fat_sector_buffer = (u8*)kmalloc(512);
	if (!fat_sector_buffer) return;

	//read the existing sector, modify, then write back...
	ata_read_sector(fat_sector, fat_sector_buffer);
	*(u32*)&fat_sector_buffer[fat_offset] = (value & 0x0FFFFFFF);//FAT32 uses 28 bit
	ata_write_sector(fat_sector, fat_sector_buffer);

	kfree(fat_sector_buffer);
}

//scans the FAT area for the first cluster than contains 0x00000000
u32 fat32_find_free_cluster(void)
{
	if (mounted_bpb == NULL) return 0;

	u8* fat_sector_buffer = (u8*)kmalloc(512);
	if (!fat_sector_buffer) return 0;

	//calculate how many total clusters are available on the drive
	u32 total_data_sectors = mounted_bpb->total_sectors_32 - data_start_sector;
	u32 total_clusters = total_data_sectors / mounted_bpb->sectors_per_cluster;

	//start scanning from cluster 2
	for (u32 cluster = 2; cluster < total_clusters + 2; cluster++)
	{
		u32 fat_sector = partition_offset + fat_start_sector + ((cluster * 4) / 512);
		u32 fat_offset = (cluster * 4) % 512;

		if (fat_offset == 0 || cluster == 2)
		{
			ata_read_sector(fat_sector, fat_sector_buffer);
		}

		u32 entry_val = *(u32*)&fat_sector_buffer[fat_offset] & 0x0FFFFFFF;
		if (entry_val == 0)
		{
			kfree(fat_sector_buffer);
			return cluster; //bingo! found a free slot!
		}
	}

	kfree(fat_sector_buffer);
	return 0; //DISK full!
}

//helper to pad/format the filename to the standard 8.3 FAT format
// example "test.txt" becomes "TEST  TXT"
void format_fat_name(const char* src, u8* dest)
{
	#define TO_UPPER(c) (((c) >= 'a' && (c) <= 'z') ? ((c) - 32) : (c))
	memset(dest, ' ', 11);
	int i = 0, j = 0;
	while (src[i] != '\0' && src[i] != '.' && j < 8)
	{
		dest[j++] = TO_UPPER(src[i]);
		i++;
	}

	if (src[i] == '.')
	{
		i++; //skip the '.'
		j = 8;
		while (src[i] && j < 11)
		{
			dest[j++] = TO_UPPER(src[i]);
			i++;
		}
	}
	#undef TO_UPPER
}

int fat32_add_entry(u32 dir_cluster, const char* filename, u8 attrib, u32 starting_cluster, u32 file_size)
{
	u32 bytes_per_cluster = mounted_bpb->sectors_per_cluster * 512;
	u8* buffer = (u8*)kmalloc(bytes_per_cluster);

	u32 base_sector = fat32_cluster_to_sector(dir_cluster);
	for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
	{
		ata_read_sector(base_sector + s, buffer + (s * 512));
	}

	FAT32_DirEntry *entries = (FAT32_DirEntry*)buffer;
	u32 max_entries = bytes_per_cluster / 32;
	int target_slot = -1;

	for (u32 i = 0; i < max_entries; ++i)
	{
		//found an empty or deleted slot...
		if (entries[i].name[0] == 0x00 || entries[i].name[0] == 0xE5)
		{
			target_slot = i;
			break;
		}
	}

	if (target_slot == -1)
	{
		kfree(buffer);
		return -1; //the directory is full if no free bytes are found
	}

	//populate the new directory entry...
	FAT32_DirEntry *new_entry = &entries[target_slot];
	format_fat_name(filename, new_entry->name);
	new_entry->attr = attrib;
	new_entry->first_cluster_lo = starting_cluster & 0xFFFF;
	new_entry->first_cluster_hi = (starting_cluster >> 16) & 0xFFFF;
	new_entry->file_size = file_size;
	//clear timestamps / creation dates for simplicity right now
	new_entry->nt_res = 0;
	new_entry->crt_time_ten = 0;

	//writ the updated cluster back to the disk
	for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; s++)
	{
		ata_write_sector(base_sector + s, buffer + (s * 512));
	}

	kfree(buffer);
	return 0; //success
}

void fat32_sync_directory_metadata(vfs_node_t *file_node, u32 parent_dir_cluster, u32 newsize, u32 first_cluster)
{
    u8 *sector_buffer = (u8*)kmalloc(512);
    if (!sector_buffer) return;

    u32 dir_sector = fat32_cluster_to_sector(parent_dir_cluster);
    FAT32_DirEntry *entries = (FAT32_DirEntry*)sector_buffer;

    //standard search loops acros the directory sectors
    for (u32 s = 0; s < mounted_bpb->sectors_per_cluster; ++s)
    {
        ata_read_sector(dir_sector + s, sector_buffer);

        for (int i = 0; i < 16; ++i)
        {
            //match based on the inode / starting cluster tag
            u32 entry_cluster = ((u32)entries[i].first_cluster_hi << 16) | entries[i].first_cluster_lo;
            if (entry_cluster == file_node->inode)
            {
                //update file size & starting cluster...
                entries[i].file_size = newsize;
                entries[i].first_cluster_hi = (u16)(first_cluster >> 16);
                entries[i].first_cluster_lo = (u16)(first_cluster & 0xFFFF);

                //commit back to physical disk sector
                ata_write_sector(dir_sector + s, sector_buffer);
                kfree(sector_buffer);
                return;
            }
        }
    }
    kfree(sector_buffer);
}

void cmd_touch(const char *filename)
{
	if (mounted_bpb == NULL)
	{
		vga_puts("[ ERROR ] - No mounted disk/drive. Cannot create file. \n");
		return;
	}
	//assume we track current_dir_cluster dynamically in the shell
	if (fat32_add_entry(current_dir_cluster, filename, 0x00, 0, 0) == 0)
	{
		vga_puts("[ SUCCESS ] - ");
		vga_puts(filename);
		vga_puts(" created successfully. \n");
	} else {
		vga_puts("[ ERROR ] - Could not create file. \n");
	}
}

//command: ls
void cmd_ls(u32 target_cluster)
{
	if (mounted_bpb == NULL)
	{
		vga_puts(" bin/"); //fallback to mock if hardware not mounted
		return;
	}

	u32 sector = fat32_cluster_to_sector(target_cluster);
	u8* buffer = (u8*)kmalloc(512);
	if (!buffer) return;

	ata_read_sector(sector, buffer);
	FAT32_DirEntry *entries = (FAT32_DirEntry*)buffer;

	//loop through 16 available 32-byte directory entry records in this 512 byte sector
	for (int i = 0; i < 16; ++i)
	{
		if (entries[i].name[0] == 0x00) break; //EOD(End Of Directory) stream mark
		if (entries[i].name[0] == 0xE5) continue; //deleted entry skip
		if (entries[i].attr == 0x0F) continue; //long file name helper metadeata skip
		if (entries[i].attr & 0x08) continue; //this skipes NO-NAME labels
		vga_puts(" ");
		//print main name(8 chars max)
		for (int c = 0; c < 8; c++)
		{
			if (entries[i].name[c] != ' ') vga_put_c(entries[i].name[c]);
		}

		//if it is a directory attribute (0x10 flag)
		if (entries[i].attr & 0x10)
		{
			vga_puts("/");
		} else { //it's a file and append its dot extension
			vga_puts(".");
			for (int c = 8; c < 11; c++)
			{
				if (entries[i].name[c] != ' ') vga_put_c(entries[i].name[c]);
			}
			vga_puts("   (");
			vga_put_num(entries[i].file_size);
			vga_puts(" bytes)");
		}
		vga_puts("\n");
	}
	kfree(buffer);
}

//Command: pwd
void cmd_pwd(void)
{
	vga_puts(current_working_dir);
	vga_puts("\n");
}

//Command: cd <folder>
void cmd_cd(const char* target_folder)
{
    if (mounted_bpb == NULL)
    {
        vga_puts("[ ERROR ] - No physical hardware mounted to support directory switching.\n");
        return;
    }

    // Edge case: Handle going back to root directory shortcut "cd /"
    if (strcmp(target_folder, "/") == 0)
    {
        current_dir_cluster = mounted_bpb->root_cluster;
        current_working_dir[0] = '/';
        current_working_dir[1] = '\0';
        return;
    }

    // Edge case: Handle going back to previous directory "cd .."
        if (strcmp(target_folder, "..") == 0)
        {
            if (strcmp(current_working_dir, "/") == 0) return; // Already at root

            u32 sector = fat32_cluster_to_sector(current_dir_cluster);
            u8 *buffer = (u8*)kmalloc(512);
            if (!buffer) return;

            ata_read_sector(sector, buffer);
            FAT32_DirEntry *entries = (FAT32_DirEntry*)buffer;
            int found = 0;

            for (int i = 0; i < 16; i++)
            {
                // FAT32 physically stores '..' starting with two dots
                if (entries[i].name[0] == '.' && entries[i].name[1] == '.')
                {
                    current_dir_cluster = ((u32)entries[i].first_cluster_hi << 16) | entries[i].first_cluster_lo;

                    // FAT32 Specification: A cluster value of 0 in the ".." entry points to the root directory
                    if (current_dir_cluster == 0) {
                        current_dir_cluster = mounted_bpb->root_cluster;
                    }
                    found = 1;
                    break;
                }
            }
            kfree(buffer);

            if (found)
            {
                // Rewind the current_working_dir string
                int len = 0;
                while (current_working_dir[len] != '\0') len++;

                // Step back from the trailing slash
                if (len > 1 && current_working_dir[len-1] == '/') {
                    len--;
                }

                // Delete characters until we hit the previous slash
                while (len > 0 && current_working_dir[len-1] != '/') {
                    len--;
                }

                // Cap the string
                if (len == 0) {
                    current_working_dir[0] = '/';
                    current_working_dir[1] = '\0';
                } else {
                    current_working_dir[len] = '\0';
                }
            }
            return;
        }

    u32 sector = fat32_cluster_to_sector(current_dir_cluster);
    u8 *buffer = (u8*)kmalloc(512);
    if (!buffer) return;

    ata_read_sector(sector, buffer);
    FAT32_DirEntry *entries = (FAT32_DirEntry*)buffer;
    int found = 0;

    for (int i = 0; i < 16; i++)
    {
        if (entries[i].name[0] == 0x00) break;
        if (entries[i].name[0] == 0xE5) continue;

        //Fix: skip the volume labels too...
        if (entries[i].attr == 0x0F) continue;
        if (entries[i].attr & 0x08) continue;

        // Check if the item is a valid directory
        if (entries[i].attr & 0x10)
        {
            // Use our newly constructed parser to see if the directory names align!
            if (fat32_compare_name(target_folder, entries[i].name) == 0)
            {
                // Pull the 32-bit destination cluster address from high and low entry word values
                current_dir_cluster = ((u32)entries[i].first_cluster_hi << 16) | entries[i].first_cluster_lo;

                // Concatenate the new folder name onto our human-readable path string
                int len = 0;
                while (current_working_dir[len] != '\0') len++;

                int t_idx = 0;
                while (target_folder[t_idx] != '\0' && len < 250)
                {
                    current_working_dir[len++] = target_folder[t_idx++];
                }
                current_working_dir[len++] = '/';
                current_working_dir[len] = '\0';

                found = 1;
                break;
            }
        }
    }

    if (!found)
    {
        vga_puts("/bin/ursh: cd: no such file or directory: ");
        vga_puts(target_folder);
        vga_puts("\n");
    }

    kfree(buffer);
}

#define _VGA_ADDRESS 0xB8000 //vga memory address
#define _VGA_COLS 80
#define _VGA_ROWS 25
#define _VGA_ATTR 0x0E //yellow on black

#define _PIC1_COMMAND 0x20
#define _PIC1_DATA    0x21 //master PIC
#define _PIC2_COMMAND 0xA0
#define _PIC2_DATA    0xA1	//slave PIC

#define _ICW1_INIT    0x11
#define _ICW4_8086    0x01

#define _VGA_BUFFER ((volatile u16*)_VGA_ADDRESS)
static long unsigned int cursor_pos = 0;

void pic_remap(void);
void outb(u16 port, u8 val);
void serial_puts(const char* str);
void serial_put_c(char c);
void mouse_wait(u8 type);
void mouse_write(u8 val);
void mouse_init(void);

// Sends a 16-bit word to a hardware port
void outw(u16 port, u16 val) {
    __asm__ volatile ("outw %0, %1" : : "a"(val), "Nd"(port));
}

u16 inw(u16 port)
{
	u16 ret;
	__asm__ volatile("inw %1, %0" : "=a"(ret) : "Nd"(port));
	return ret;
}

int strcmp(const char* s1, const char* s2)
{
	while (*s1 && (*s1 == *s2))
	{
		s1++;
		s2++;
	}
	return *(const unsigned char*)s1 - *(const unsigned char*)s2;
}

void memset(void *dest, u8 val, u32 len)
{
	u8* ptr = (u8*)dest;
	while (len--)
	{
		*ptr++ = val;
	}
}

void vga_scroll(void)
{
	u16 *vga = (u16*)_VGA_ADDRESS;

	//physically shift rows 1 to 24 up by one row
	for (int y = 0; y < _VGA_ROWS - 1; y++)
	{
		for (int x = 0; x < _VGA_COLS; x++)
		{
			vga[y * _VGA_COLS + x] = vga[(y + 1) * _VGA_COLS + x];
		}
	}

	//clear out the very bottom row (row 24) to make it empty space
	u16 blank_cell = (u16)' ' | ((u16)_VGA_ATTR << 8);
	for (int x = 0; x < _VGA_COLS; x++)
	{
		vga[(_VGA_ROWS - 1) * _VGA_COLS + x] = blank_cell;
	}
}

void vga_put_c(char c)
{
	//handle new-line character...
	if (c == '\n')
	{
		cursor_pos = (cursor_pos / _VGA_COLS + 1) * _VGA_COLS;
	} else if (c == '\b'){
		//handling backspace...
		if (cursor_pos > 0)
		{
			cursor_pos--;
			_VGA_BUFFER[cursor_pos] = (u16)32 | ((u16)_VGA_ATTR << 8);
		}
	} else {
		//print the char like that if it's not backspace or new-line...
		_VGA_BUFFER[cursor_pos] = (u16)c | ((u16)_VGA_ATTR << 8);
		cursor_pos++;
	}

	//automatic scroll check
	if (cursor_pos >= _VGA_COLS * _VGA_ROWS)
	{
		vga_scroll();
		//snap cursor bact to the very start of the very lat line
		cursor_pos = (_VGA_ROWS - 1) * _VGA_COLS;
	}

	// Keep the physical blinking cursor locked to our tracking pointer
	outb(0x3D4, 0x0F);
	outb(0x3D5, (u8)(cursor_pos & 0xFF));
	outb(0x3D4, 0x0E);
	outb(0x3D5, (u8)((cursor_pos >> 8) & 0xFF));
}

//prints text to vga buffer
void vga_puts(const char* str)
{
	while(*str)
	{
		vga_put_c(*str++);
	}
}

void vga_put_num(u32 num)
{
	if (num == 0)
	{
		vga_put_c('0');
		return;
	}
	char buf[12];
	int i = 10;
	buf[11] = '\0';
	while (num > 0 && i >= 0)
	{
		buf[i--] = (num % 10) + '0';
		num /= 10;
	}
	vga_puts(&buf[i + 1]);
}

//this method remaps the entries since long ago the PIC and Exceptions collide...
//...so this maps the PIC IRQs at different addresses from the CPU Exceptions
// Small delay for I/O operations
void io_wait(void) {
    outb(0x80, 0);
}

void pic_remap(void) {
    // Start initialization sequence
    outb(_PIC1_COMMAND, _ICW1_INIT); io_wait();
    outb(_PIC2_COMMAND, _ICW1_INIT); io_wait();

    // Set offsets (Master: 0x20, Slave: 0x28)
    outb(_PIC1_DATA, 0x20); io_wait();
    outb(_PIC2_DATA, 0x28); io_wait();

    // Tell Master there is a slave PIC at IRQ2
    outb(_PIC1_DATA, 4); io_wait();
    // Tell Slave its cascade identity
    outb(_PIC2_DATA, 2); io_wait();

    // Set mode to 8086/88
    outb(_PIC1_DATA, _ICW4_8086); io_wait();
    outb(_PIC2_DATA, _ICW4_8086); io_wait();

    // Mask all interrupts until ready
    outb(_PIC1_DATA, 0xFF); io_wait();
    outb(_PIC2_DATA, 0xFF); io_wait();
}

//outb bytes, sends data to ports/hardware(i guess)
void outb(u16 port, u8 val) {
    __asm__ volatile ("outb %0, %1" : : "a"(val), "Nd"(port));
}

//opposite or outb, reads...
u8 inb(u16 port)
{
	u8 ret;
	__asm__ volatile ("inb %1, %0" : "=a"(ret) : "Nd"(port));
	return ret;
}

//PIC End Of Interrupt, this tells the PIC when an ISR is over...
//...and it should tell CPU to continuw what is was doing "hlt" hehe
void pic_eoi(int irq)
{
	if (irq >= 8) outb(_PIC2_COMMAND, 0x20);
	outb(_PIC1_COMMAND, 0x20);
}

typedef struct {
    u16 offset_low;      // Low 16 bits of handler address
    u16 selector;        // Segment selector(normally 0x08 form our GDT remember?)
    u8 zero;             // Always 0
    u8 type_attr;        // 0x8E = interrupt gate
    u16 offset_high;     // High 16 bits of handler address
} __attribute__((packed)) IDT_Entry;

typedef struct {
    u16 size;            // Size of IDT - 1
    u32 address;         // Address of IDT array
} __attribute__((packed)) IDTR;

#define _IDT_ENTRIES 256
static IDT_Entry idt[_IDT_ENTRIES]; //create the 256 IDT entries

//printf hexadecimal text...
void vga_put_hex(u32 num)
{
    const char *hex = "0123456789ABCDEF";

    vga_puts("0x");

    // Print each hex digit
    for (int i = 7; i >= 0; i--)
    {
        u8 digit = (num >> (i * 4)) & 0xF;
        vga_put_c(hex[digit]);
    }
}

// Function to set one IDT entry
void idt_set_entry(int index, u32 handler_addr, u16 selector, u8 type_attr)
{
    idt[index].offset_low = handler_addr & 0xFFFF;           // Low 16 bits
    idt[index].offset_high = (handler_addr >> 16) & 0xFFFF;  // High 16 bits
    idt[index].selector = selector;
    idt[index].zero = 0;
    idt[index].type_attr = type_attr;
}

// Load IDT into CPU
void idt_load(void)
{
    static IDTR idtr; // Static ensures it stays in memory
    idtr.size = (sizeof(IDT_Entry) * _IDT_ENTRIES) - 1;
    idtr.address = (u32)&idt;

    __asm__ volatile("lidt %0" : : "m"(idtr));
}

