#define _PIT_COMMAND 0x43
#define _PIT_CHANNEL0 0x40

// Configure PIT to fire at a specific frequency (Hz)
void pit_init(u32 frequency) {
    // 1193182 Hz is the internal PIT oscillator frequency
    u32 divisor = 1193182 / frequency;

    // Command byte: Channel 0, access lo/hi byte, square wave mode, 16-bit binary
    // 0x36 = 00110110b
    outb(_PIT_COMMAND, 0x36);

    // Send divisor split across low byte and high byte
    outb(_PIT_CHANNEL0, (u8)(divisor & 0xFF));
    outb(_PIT_CHANNEL0, (u8)((divisor >> 8) & 0xFF));
}

static u32 timer_ticks = 0; //timer ticks...

void sleep(u32 milliseconds)
{
	u32 target_ticks = timer_ticks + milliseconds;

	while (timer_ticks < target_ticks)
	{
		__asm__ volatile("hlt");
	}
}

__attribute__((interrupt)) void timer_handler(void *frame)
{
	timer_ticks++;
	pic_eoi(0);
	//we'll make use of this again when making a sleep() command...
}

//buffer for keyboard buffer (keyboard driver)
#define _BUFFER_SIZE 64

//array of characters for the buffer
volatile char key_buffer[_BUFFER_SIZE];
//keeps track of current buffer status
volatile int buffer_head = 0;
volatile int buffer_tail = 0;

// Add a character to the buffer
void buffer_push(char c) {
    int next_head = (buffer_head + 1) % _BUFFER_SIZE;

    //prevent ring buffer overwrite if queue is full
    if (next_head == buffer_tail)
    {
        return;     //drop key or handle overrun safely
    }

    key_buffer[buffer_head] = c;
    buffer_head = next_head;
}

// Remove and return a character from the buffer
char buffer_pop(void) {
    //atomically check buffer bounds
    if (buffer_head == buffer_tail) return 0;

    char c = key_buffer[buffer_tail];
    buffer_tail = (buffer_tail + 1) % _BUFFER_SIZE;
    return c;
}

//special case keys for the keyboard interrpt and drivers
int shift_pressed = 0;
int caps_lock = 0;
int ctrl_key = 0;

// The index is the scan code. 0 means "no character".
//current characters the CPU can read from the keyboard
const char kdb_map[] = {
    0, 27, '1', '2', '3', '4', '5', '6', '7', '8', '9', '0', '-', '=', '\b',
    '\t', 'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '[', ']', '\n',
    0, 'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', ';', '\'', '`', 0, '\\',
    'z', 'x', 'c', 'v', 'b', 'n', 'm', ',', '.', '/', 0, '*', 0, ' '
};

__attribute__((interrupt)) void keyboard_handler(void *frame)
{
	u8 scancode = inb(0x60); //read from the keyboard PIC ports

	//detect if it is a break code... (key release)
	if (scancode & 0x80)
	{
		u8 release_code = scancode - 0x80;
		if (release_code == 0x2A || release_code == 0x36) //left & right SHIFT
		{
			shift_pressed = 0;
		}
	}

	//logic if it's not a break code...
	else {
		if (scancode == 0x2A || scancode == 0x36) //left & right SHIFT
		{
			shift_pressed = 1;
		} else if (scancode == 0x3A){
			//caps-lock...
			caps_lock = !caps_lock;
		} else if (scancode == 0x0E){
			//backspace '\b'
			buffer_push('\b');
		} else {
			char c = kdb_map[scancode];
			if (c != 0)
			{
				//if shift is pressed...
				if (shift_pressed && c >= 'a' && c <= 'z')
				{
					//convert to upper-case...
					c -= 32;
				} else if (caps_lock && c >= 'a' && c <='z'){
					//if caps_lock is pressed...
					c -= 32;
				}

				buffer_push(c);
			}
		}
	}
	pic_eoi(1);
}

