//MOUSE INIT, waking up the mouse...
// mouse wait method, to wait for input to be data to be ready or...
// ...input to be empty
void mouse_wait(u8 type)
{
	u32 timeout = 100000;
	if (type == 0) //wait for ready data to be read...
	{
		while (--timeout && !(inb(0x64) & 1));
	} else { //wait for buffer to be empty to write...
		while (--timeout && (inb(0x64) & 2));
	}
}

//writes to the mouse, [data]
void mouse_write(u8 val)
{
	mouse_wait(1); //wait for input to be empty
	outb(0x64, 0xD4); //send to the Mouse PIC port that we wanna write
	mouse_wait(1);
	outb(0x60, val); //send the actual data
}

//initializes the mouse
void mouse_init(void)
{
    u8 status;

    mouse_wait(1);
    outb(0x64, 0xA8); // Enable mouse port

    mouse_wait(1);
    outb(0x64, 0x20); // Read Command Byte
    mouse_wait(0);
    status = inb(0x60);
    status |= 3;      // SET BOTH BIT 0 (Keyboard) AND BIT 1 (Mouse)

    mouse_wait(1);
    outb(0x64, 0x60); // Write Command Byte
    mouse_wait(1);
    outb(0x60, status);

    mouse_write(0xF6); // Set defaults
    mouse_write(0xF4); // Enable data reporting
}

//mouse driver init...
u8 mouse_packet[3];
u8 mouse_cycle = 0; //tracks which byte from 0,1,2 we are on!

__attribute__((interrupt)) void mouse_handler(void *frame)
{
	u8 status = inb(0x64); //read status register to ensure data is ready

	if (status & 0x01) //if there's data to read...
	{
		u8 data = inb(0x60);

		switch (mouse_cycle)
		{
			case 0: //byte 1: status
				mouse_packet[0] = data;
				mouse_cycle = 1;
				break;
			case 1: //byte 2: X-Movement
				mouse_packet[1] = data;
				mouse_cycle = 2;
				break;
			case 2: //byte 3: Y-Movement
				mouse_packet[2] = data;
				mouse_cycle = 0; //Reset for the next packet
				//Here we will process the full packet
				serial_puts("mouse moved!");
				break;
		}
	}
	pic_eoi(12);
}

// Generic interrupt handler
// This handles unexpected interrupts that haven't been mapped yet...
__attribute__((interrupt)) void default_interrupt_handler(void *frame) {
    vga_puts("\n=== UNEXPECTED INTERRUPT ===\n");
    vga_puts("An unexpected interrupt occurred! System halted.\n");
    while(1) {
        __asm__("hlt");
    }
}

//initializees the IDT
void idt_init(void)
{
    __asm__("cli"); //clear interrupts

    vga_puts("Initializing IDT...\n");

    // Clear all IDT entries first and set them to default handler
    for (int i = 0; i < _IDT_ENTRIES; i++)
    {
        // Use 0x8E for interrupt gate, Present bit set, ring 0, interrupt gate
        idt_set_entry(i, (u32)default_interrupt_handler, 0x08, 0x8E);
    }

    // Set up specific handlers (will overwrite default for these)
    idt_set_entry(0, (u32)divide_by_zero_handler, 0x08, 0x8E);
    idt_set_entry(1, (u32)debug_handler, 0x08, 0x8E);
    idt_set_entry(2, (u32)nmi_handler, 0x08, 0x8E);
    idt_set_entry(3, (u32)breakpoint_handler, 0x08, 0x8E);
    idt_set_entry(4, (u32)overflow_handler, 0x08, 0x8E);
    idt_set_entry(5, (u32)bound_range_handler, 0x08, 0x8E);
    idt_set_entry(6, (u32)invalid_opcode_handler, 0x08, 0x8E);
    idt_set_entry(7, (u32)device_not_available_handler, 0x08, 0x8E);
    idt_set_entry(8, (u32)double_fault_handler, 0x08, 0x8E);
    idt_set_entry(10, (u32)invalid_tss_handler, 0x08, 0x8E);
    idt_set_entry(11, (u32)segment_not_present_handler, 0x08, 0x8E);
    idt_set_entry(12, (u32)stack_fault_handler, 0x08, 0x8E);
    idt_set_entry(13, (u32)general_protection_fault_handler, 0x08, 0x8E);
    idt_set_entry(14, (u32)page_fault_handler, 0x08, 0x8E);
    idt_set_entry(16, (u32)floating_point_exception_handler, 0x08, 0x8E);
    idt_set_entry(17, (u32)alignment_check_handler, 0x08, 0x8E);
    idt_set_entry(18, (u32)machine_check_handler, 0x08, 0x8E);
    idt_set_entry(19, (u32)simd_floating_point_exception_handler, 0x08, 0x8E);

    // IRQ handlers (PIC mapped IRQs)
    idt_set_entry(0x20, (u32)timer_handler, 0x08, 0x8E); // IRQ0 - Timer
    idt_set_entry(0x21, (u32)keyboard_handler, 0x08, 0x8E); // IRQ1 - Keyboard
    idt_set_entry(0x24, (u32)com1_handler, 0x08, 0x8E); // IRQ4 - COM1
    idt_set_entry(0x2C, (u32)mouse_handler, 0x08, 0x8E); // IRQ12 - Mouse

    // Load IDT into CPU
    idt_load();
    //__asm__("sti"); //start interrupts
}

